import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long total = 0;
        int highest = 0;
        for(int i = 0; i < n; i++) {
            int amount = sc.nextInt();
            total += amount;
            if(amount > highest) {
                highest = amount;
            }
        }
        System.out.println("Total: " + total);
        System.out.println("Highest: " + highest);
    }
}

import java.util.Scanner;

