import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        do {
            System.out.println(n);
            n--;
        } while(n >= 1);
        System.out.println("Liftoff!");
    }
}
